{% from "hipersign_trading/templates/print/macros.html" import styles, header, items, totals, signs, bank %}
{{ styles() }}
<div class="hs-doc">
{% set exp = doc.hs_zero_rated %}{% if doc.is_return %}{{ header("TAX CREDIT NOTE", "إشعار دائن ضريبي", doc.name, doc.posting_date, doc.company) }}<div class="hs-two" style="margin-bottom:8px"><div><b>Against tax invoice · مقابل الفاتورة:</b> {{ doc.return_against or "" }}</div><div><b>Reason · السبب:</b> {{ doc.hs_return_reason or "" }}</div></div>{% else %}{{ header("TAX INVOICE — EXPORT" if exp else "TAX INVOICE", "فاتورة ضريبية", doc.name, doc.posting_date, doc.company) }}{% endif %}
<div class="hs-two"><div><div class="hs-h4">Bill to · فاتورة إلى</div><b>{{ doc.customer_name }}</b><br>{{ doc.address_display or "" }}{% if doc.contact_display %}<br>Attn: {{ doc.contact_display }}{% if doc.contact_mobile %} · {{ doc.contact_mobile }}{% endif %}{% endif %}{% if doc.tax_id %}<br>TRN {{ doc.tax_id }}{% endif %}</div><div><div class="hs-h4">Details · التفاصيل</div>Due date: {{ frappe.utils.formatdate(doc.due_date) }}<br>Currency: {{ doc.currency }}{% if doc.po_no %}<br>Customer PO: {{ doc.po_no }}{% endif %}{% if doc.hs_export_shipment %}<br>Export shipment: {{ doc.hs_export_shipment }}{% endif %}</div></div>
{{ items(doc) }}
{{ totals(doc) }}
{% if exp %}<div class="hs-note"><b>Zero-rated export of goods — VAT 0%.</b> Evidence of export is held on file.</div>{% endif %}
<div class="hs-tot"><div><span>Outstanding · المستحق</span><b>{{ doc.get_formatted("outstanding_amount") }}</b></div></div>
{{ bank(doc) }}
</div>
